package sfz.kafka.l11.demo;

import org.apache.avro.Schema;
import org.apache.avro.SchemaCompatibility;
import org.apache.avro.generic.GenericData;
import org.apache.avro.generic.GenericDatumReader;
import org.apache.avro.generic.GenericDatumWriter;
import org.apache.avro.generic.GenericRecord;
import org.apache.avro.io.BinaryEncoder;
import org.apache.avro.io.DecoderFactory;
import org.apache.avro.io.EncoderFactory;

import java.io.ByteArrayOutputStream;
import java.nio.ByteBuffer;
import java.util.HexFormat;

/**
 * One payment, written with version 1 of its Avro schema and read back with three reader schemas: the same one,
 * one that adds a field with a default, and one that adds a field without a default. No broker, no registry.
 */
public class AvroEvolutionDemo {
    static final String V1 = """
            {"type": "record", "name": "Payment", "fields": [
              {"name": "id", "type": "string"},
              {"name": "account", "type": "string"},
              {"name": "amount", "type": "long"}]}""";
    static final String V2 = """
            {"type": "record", "name": "Payment", "fields": [
              {"name": "id", "type": "string"},
              {"name": "account", "type": "string"},
              {"name": "amount", "type": "long"},
              {"name": "currency", "type": "string", "default": "EUR"}]}""";
    static final String V3 = """
            {"type": "record", "name": "Payment", "fields": [
              {"name": "id", "type": "string"},
              {"name": "account", "type": "string"},
              {"name": "amount", "type": "long"},
              {"name": "merchantId", "type": "string"}]}""";

    public static void main(String[] args) throws Exception {
        Schema v1 = new Schema.Parser().parse(V1), v2 = new Schema.Parser().parse(V2), v3 = new Schema.Parser().parse(V3);

        // the producer's side: a v1 payment, encoded as Avro binary
        GenericRecord payment = new GenericData.Record(v1);
        payment.put("id", "pay-1");
        payment.put("account", "acct-17");
        payment.put("amount", 4000L);
        var out = new ByteArrayOutputStream();
        BinaryEncoder encoder = EncoderFactory.get().binaryEncoder(out, null);
        new GenericDatumWriter<GenericRecord>(v1).write(payment, encoder);
        encoder.flush();
        byte[] avro = out.toByteArray();
        System.out.println("v1 payment as Avro binary, " + avro.length + " bytes: " + HexFormat.ofDelimiter(" ").formatHex(avro));

        // what a registry-aware serializer sends: magic byte 0, the schema id (say 1) as 4 bytes, then the Avro bytes
        byte[] framed = ByteBuffer.allocate(5 + avro.length).put((byte) 0).putInt(1).put(avro).array();
        System.out.println("with the 5-byte registry prefix, " + framed.length + " bytes: " + HexFormat.ofDelimiter(" ").formatHex(framed, 0, 5) + " | ...");

        // the consumer's side: the writer schema comes with the data (by id), the reader schema is the consumer's own
        for (var reader : new Schema[]{v1, v2, v3}) {
            String name = reader == v1 ? "v1" : reader == v2 ? "v2" : "v3";
            try {
                var decoder = DecoderFactory.get().binaryDecoder(avro, null);
                GenericRecord read = new GenericDatumReader<GenericRecord>(v1, reader).read(null, decoder);
                System.out.println("reader " + name + " reads it: " + read);
            } catch (Exception e) {
                System.out.println("reader " + name + " fails:    " + e.getClass().getSimpleName() + ": " + e.getMessage());
            }
        }
        // Avro's own check, the one a registry runs before it accepts a new version
        System.out.println("can v2 read v1 data? " + SchemaCompatibility.checkReaderWriterCompatibility(v2, v1).getType());
        System.out.println("can v3 read v1 data? " + SchemaCompatibility.checkReaderWriterCompatibility(v3, v1).getType());
    }
}

package sfz.kafka.l11.demo;

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Talks to Schema Registry on localhost:8081 over its REST API: registers version 1 of a payment schema, then asks
 * whether two changes are compatible under the subject's mode, and tries to register both.
 */
public class RegistryDemo {
    static final String REGISTRY = "http://localhost:8081";
    static final HttpClient http = HttpClient.newHttpClient();

    static final String V1 = """
            {"type": "record", "name": "Payment", "fields": [
              {"name": "id", "type": "string"}, {"name": "account", "type": "string"}, {"name": "amount", "type": "long"}]}""";
    static final String V2 = """
            {"type": "record", "name": "Payment", "fields": [
              {"name": "id", "type": "string"}, {"name": "account", "type": "string"}, {"name": "amount", "type": "long"},
              {"name": "currency", "type": "string", "default": "EUR"}]}""";
    static final String V3 = """
            {"type": "record", "name": "Payment", "fields": [
              {"name": "id", "type": "string"}, {"name": "account", "type": "string"}, {"name": "amount", "type": "long"},
              {"name": "currency", "type": "string", "default": "EUR"}, {"name": "merchantId", "type": "string"}]}""";

    public static void main(String[] args) throws Exception {
        // one subject per run; the serializer's default name for a topic's values is "<topic>-value"
        String subject = "payments-" + System.currentTimeMillis() % 100_000 + "-value";
        call("GET", "/config", null);
        call("POST", "/subjects/" + subject + "/versions", V1);                                   // register v1
        call("POST", "/compatibility/subjects/" + subject + "/versions/latest", V2);              // v2: adds currency, with a default
        call("POST", "/subjects/" + subject + "/versions", V2);
        call("POST", "/compatibility/subjects/" + subject + "/versions/latest?verbose=true", V3); // v3: adds merchantId, no default
        call("POST", "/subjects/" + subject + "/versions", V3);
        call("GET", "/subjects/" + subject + "/versions", null);
    }

    static void call(String method, String path, String avroSchema) throws Exception {
        var request = HttpRequest.newBuilder(URI.create(REGISTRY + path)).header("Content-Type", "application/vnd.schemaregistry.v1+json");
        if (avroSchema == null) request.GET();
        else request.POST(HttpRequest.BodyPublishers.ofString("{\"schema\": " + quote(avroSchema) + "}"));
        HttpResponse<String> response = http.send(request.build(), HttpResponse.BodyHandlers.ofString());
        String line = method + " " + path + "\n  -> " + response.statusCode() + " " + summary(response.body());
        System.out.println(line.replaceAll("payments-\\d+-value", "payments-value"));   // the subject has this run's number
    }

    /** The parts of a reply worth reading: ids, verdicts and the reason a change was refused. */
    static String summary(String body) {
        Matcher reason = Pattern.compile("errorType:\\\\?\"(\\w+)\\\\?\", description:\\\\?\"([^\"\\\\]+)").matcher(body);
        String head = body.replaceAll("\"schema\":\".*\"", "\"schema\":...").replaceAll(",\"messages\":.*|, details: .*|,\"guid\":\"[^\"]*\"", "");
        return reason.find() ? head + "  [" + reason.group(1) + ": " + reason.group(2) + "]" : head;
    }

    static String quote(String json) {
        return "\"" + json.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", " ") + "\"";
    }
}

