    try (var payment = db.prepareStatement("INSERT INTO payment (id, account, amount, status) VALUES (?, ?, ?, 'AUTHORIZED')");
         var event = db.prepareStatement("INSERT INTO outbox (id, aggregatetype, aggregateid, type, payload) "
