        payment.setString(1, paymentId); payment.setString(2, account); payment.setLong(3, cents);
        payment.executeUpdate();
        event.setObject(1, UUID.randomUUID());                 // the event id consumers dedupe on
        event.setString(2, account);                           // becomes the Kafka key: per-account order
        event.setString(3, "{\"paymentId\": \"" + paymentId + "\", \"amount\": " + cents + "}");
        event.executeUpdate();
    }
    db.commit();                                               // both rows, or neither
}

