fun readProblems(reader: RecordSchema, writer: RecordSchema): List<String> {
    if (reader.name != writer.name) return listOf("NAME_MISMATCH")
    val written = writer.fields.associateBy { it.name }
    return reader.fields.mapNotNull { f ->
        val w = written[f.name]
        when {
            w != null && !canPromote(w.type, f.type) -> "TYPE_MISMATCH: ${f.name}"
            w == null && !f.hasDefault -> "READER_FIELD_MISSING_DEFAULT_VALUE: ${f.name}"
            else -> null   // same field, or the reader's default fills it; extra writer fields are skipped
        }
    }
}
// FORWARD, remove currency: yes. Old readers (v2) have currency with a default, so they read new records.
// BACKWARD, add merchantId with no default: no. A new reader can't fill it from old records: HTTP 409.

