static List<String> readProblems(RecordSchema reader, RecordSchema writer) {
    if (!reader.name().equals(writer.name())) return List.of("NAME_MISMATCH");
    Map<String, Field> written = new HashMap<>();
    for (Field f : writer.fields()) written.put(f.name(), f);
    List<String> problems = new ArrayList<>();
    for (Field f : reader.fields()) {
        Field w = written.get(f.name());
        if (w != null && !canPromote(w.type(), f.type())) problems.add("TYPE_MISMATCH: " + f.name());
        else if (w == null && !f.hasDefault()) problems.add("READER_FIELD_MISSING_DEFAULT_VALUE: " + f.name());
        // otherwise: same field, or the reader's default fills it; extra writer fields are skipped
    }
    return problems;
}
// FORWARD, remove currency: yes. Old readers (v2) have currency with a default, so they read new records.
// BACKWARD, add merchantId with no default: no. A new reader can't fill it from old records: HTTP 409.
